def combinations(n, k):
    import math
    return math.comb(n, k)

def calculate_ratio_K_n(n):
    if n < 4:
        return 0.0
    f_G = combinations(n, 3)
    g_G = combinations(n, 4)
    if f_G == 0:
        # Should only happen if n < 3, handled above
        return 0.0
    return (g_G**3) / (f_G**4)

print(f"R(K_4) = {calculate_ratio_K_n(4)}")
print(f"R(K_7) = {calculate_ratio_K_n(7)}")
print(f"R(K_8) = {calculate_ratio_K_n(8)}")
print(f"R(K_10) = {calculate_ratio_K_n(10)}")
